head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "41.4",
        "col2": "39.3",
        "col3": "9.3",
        "col4": ""
    }, {
        "col1": "40",
        "col2": "39",
        "col3": "1",
        "col4": ""
    }, {
        "col1": "31.4",
        "col2": "39.3",
        "col3": "9.3",
        "col4": ""
    }, {
        "col1": "21.4",
        "col2": "39.3",
        "col3": "9.3",
        "col4": ""
    }, {
        "col1": "41.4",
        "col2": "39.3",
        "col3": "9.3",
        "col4": ""
    }, {
        "col1": "41",
        "col2": "39",
        "col3": "10",
        "col4": ""
    }]
    dataList1.setJSON(jsonData);
    gridView1.setCellClass(0, 0, "gridCSS");
    var index = gridView1.getTotalRow();
    for (var i = 0; i <= index; i++) {
        //console.log(i);
        dataList1.setCellData(i, "col4", Math.round((Number(dataList1.getCellData(i, "col1")) +
            Number(dataList1.getCellData(i, "col2")) +
            Number(dataList1.getCellData(i, "col3"))) * 1e12) / 1e12);
        var total = dataList1.getCellData(i, "col4");
    }
    scwin.fn_tmpDeptFilter = function(cellData, tmpParam, rowIdx) {
        var col1 = dataList1.getCellData(rowIdx, "col1");
        var col2 = dataList1.getCellData(rowIdx, "col2");
        console.log("col1:" + col1);
        console.log("col2:" + col2);
        if (col1 >= 40 && col2 > 30) {
            return true;
        }
        return false; //return이 true인 경우 적용하고 false인 경우 skip한다. 
    };
    dataList1.setColumnFilter({
        type: 'func',
        colIndex: "0",
        key: fn_tmpDeptFilter,
        condition: 'and'
    });
};
scwin.fn_tmpDeptFilter = function(cellData, tmpParam, rowIdx) {
    var col1 = dataList1.getCellData(rowIdx, "col1");
    var col2 = dataList1.getCellData(rowIdx, "col2");
    console.log("col1:" + col1);
    console.log("col2:" + col2);
    if (col1 >= 40 && col2 > 30) {
        return true;
    }
    return false; //return이 true인 경우 적용하고 false인 경우 skip한다. 
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
